def compute(vars):
    event_driven_exposure = vars["v1"]
    maturity_percentage = vars["v2"] / 100.0
    maturity_amount = event_driven_exposure * maturity_percentage

    return {
        "value": maturity_amount,
        "trace": {
            "event_driven_exposure": event_driven_exposure,
            "maturity_percentage": maturity_percentage,
            "maturity_amount": maturity_amount,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": "monetary"
            }
        }
    }
